-- IN-DOALI | Projeto Final de Dados (evolucao da base AeroBrasil)
-- MySQL 8.0.16+ | Execucao integral em banco vazio
-- Modelo ampliado: reservas, hospedagens, pacotes e historico de status
-- Preserva integralmente os 1000 INSERTs da versao anterior; total final 3555 registros.

CREATE DATABASE IF NOT EXISTS aerobrasil_reservas
    CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE aerobrasil_reservas;

-- Tabelas dependentes removidas primeiro para permitir reexecucao completa.
DROP TABLE IF EXISTS historico_reserva;
DROP TABLE IF EXISTS pacote;
DROP TABLE IF EXISTS hospedagem;
DROP TABLE IF EXISTS quarto;
DROP TABLE IF EXISTS hotel;
DROP TABLE IF EXISTS reserva;
DROP TABLE IF EXISTS voo;
DROP TABLE IF EXISTS aeroporto;
DROP TABLE IF EXISTS aeronave;
DROP TABLE IF EXISTS passageiro;

CREATE TABLE passageiro (
    id_passageiro INT PRIMARY KEY AUTO_INCREMENT,
    nome VARCHAR(120) NOT NULL,
    documento_identificacao VARCHAR(30) NOT NULL UNIQUE,
    data_nascimento DATE NOT NULL,
    contato VARCHAR(150) NULL,
    CONSTRAINT chk_passageiro_nome CHECK (CHAR_LENGTH(TRIM(nome)) > 0)
) ENGINE=InnoDB;

CREATE TABLE aeronave (
    id_aeronave INT PRIMARY KEY AUTO_INCREMENT,
    modelo VARCHAR(80) NOT NULL,
    capacidade INT NOT NULL,
    CONSTRAINT chk_aeronave_capacidade CHECK (capacidade > 0)
) ENGINE=InnoDB;

CREATE TABLE aeroporto (
    id_aeroporto INT PRIMARY KEY AUTO_INCREMENT,
    nome VARCHAR(160) NOT NULL,
    cidade VARCHAR(100) NOT NULL,
    estado_pais VARCHAR(100) NOT NULL
) ENGINE=InnoDB;

CREATE TABLE voo (
    num_voo INT PRIMARY KEY,
    data DATE NOT NULL,
    hora_partida TIME NOT NULL,
    hora_chegada TIME NOT NULL,
    id_aeronave INT NOT NULL,
    id_aeroporto_origem INT NOT NULL,
    id_aeroporto_destino INT NOT NULL,
    CONSTRAINT fk_voo_aeronave FOREIGN KEY (id_aeronave)
        REFERENCES aeronave(id_aeronave) ON DELETE RESTRICT ON UPDATE CASCADE,
    CONSTRAINT fk_voo_origem FOREIGN KEY (id_aeroporto_origem)
        REFERENCES aeroporto(id_aeroporto) ON DELETE RESTRICT ON UPDATE CASCADE,
    CONSTRAINT fk_voo_destino FOREIGN KEY (id_aeroporto_destino)
        REFERENCES aeroporto(id_aeroporto) ON DELETE RESTRICT ON UPDATE CASCADE,
    CONSTRAINT chk_voo_aeroportos CHECK (id_aeroporto_origem <> id_aeroporto_destino)
) ENGINE=InnoDB;

CREATE TABLE reserva (
    num_reserva INT PRIMARY KEY AUTO_INCREMENT,
    data_reserva DATE NOT NULL,
    num_assento VARCHAR(5) NOT NULL,
    classe VARCHAR(20) NOT NULL DEFAULT 'Economica',
    status VARCHAR(20) NOT NULL DEFAULT 'Confirmada',
    atualizado_em DATETIME NULL,
    valor_total DECIMAL(10,2) NOT NULL,
    id_passageiro INT NOT NULL,
    num_voo INT NOT NULL,
    CONSTRAINT fk_reserva_passageiro FOREIGN KEY (id_passageiro)
        REFERENCES passageiro(id_passageiro) ON DELETE RESTRICT ON UPDATE CASCADE,
    CONSTRAINT fk_reserva_voo FOREIGN KEY (num_voo)
        REFERENCES voo(num_voo) ON DELETE RESTRICT ON UPDATE CASCADE,
    CONSTRAINT uq_reserva_assento_voo UNIQUE (num_voo, num_assento),
    CONSTRAINT chk_reserva_valor CHECK (valor_total >= 0),
    CONSTRAINT chk_reserva_status CHECK (status IN ('Pendente','Confirmada','Cancelada','Concluida')),
    CONSTRAINT chk_reserva_classe CHECK (classe IN ('Economica','Executiva')),
    CONSTRAINT chk_reserva_assento CHECK (CHAR_LENGTH(TRIM(num_assento)) > 0)
) ENGINE=InnoDB;


-- Entidades de hospedagem e pacotes previstas no README original e agora implementadas.
CREATE TABLE hotel (
 id_hotel INT PRIMARY KEY AUTO_INCREMENT,
 nome VARCHAR(140) NOT NULL,
 endereco VARCHAR(180) NOT NULL,
 cidade VARCHAR(100) NOT NULL,
 estado_pais VARCHAR(100) NOT NULL,
 contato VARCHAR(100) NULL,
 categoria VARCHAR(20) NOT NULL,
 CONSTRAINT chk_hotel_categoria CHECK (categoria IN ('Economico','Executivo','Luxo'))
) ENGINE=InnoDB;

CREATE TABLE quarto (
 id_quarto INT PRIMARY KEY AUTO_INCREMENT,
 numero VARCHAR(12) NOT NULL,
 tipo VARCHAR(20) NOT NULL,
 capacidade INT NOT NULL,
 valor_diaria DECIMAL(10,2) NOT NULL,
 id_hotel INT NOT NULL,
 CONSTRAINT uq_quarto_hotel_numero UNIQUE(id_hotel,numero),
 CONSTRAINT fk_quarto_hotel FOREIGN KEY(id_hotel) REFERENCES hotel(id_hotel) ON DELETE RESTRICT ON UPDATE CASCADE,
 CONSTRAINT chk_quarto_capacidade CHECK(capacidade > 0),
 CONSTRAINT chk_quarto_valor CHECK(valor_diaria >= 0),
 CONSTRAINT chk_quarto_tipo CHECK(tipo IN ('Solteiro','Duplo','Familia'))
) ENGINE=InnoDB;

CREATE TABLE hospedagem (
 id_hospedagem INT PRIMARY KEY AUTO_INCREMENT,
 data_entrada DATE NOT NULL,
 data_saida DATE NOT NULL,
 quantidade_hospedes INT NOT NULL,
 valor_total DECIMAL(10,2) NOT NULL,
 status VARCHAR(20) NOT NULL,
 id_passageiro INT NOT NULL,
 id_quarto INT NOT NULL,
 CONSTRAINT fk_hosp_passageiro FOREIGN KEY(id_passageiro) REFERENCES passageiro(id_passageiro) ON DELETE RESTRICT ON UPDATE CASCADE,
 CONSTRAINT fk_hosp_quarto FOREIGN KEY(id_quarto) REFERENCES quarto(id_quarto) ON DELETE RESTRICT ON UPDATE CASCADE,
 CONSTRAINT chk_hosp_datas CHECK(data_saida > data_entrada),
 CONSTRAINT chk_hosp_quantidade CHECK(quantidade_hospedes > 0),
 CONSTRAINT chk_hosp_valor CHECK(valor_total >= 0),
 CONSTRAINT chk_hosp_status CHECK(status IN ('Pendente','Confirmada','Cancelada','Concluida'))
) ENGINE=InnoDB;

CREATE TABLE pacote (
 id_pacote INT PRIMARY KEY AUTO_INCREMENT,
 descricao VARCHAR(200) NOT NULL,
 data_criacao DATE NOT NULL,
 valor_total DECIMAL(10,2) NOT NULL,
 status VARCHAR(20) NOT NULL,
 num_reserva INT NOT NULL UNIQUE,
 id_hospedagem INT NOT NULL UNIQUE,
 CONSTRAINT fk_pacote_reserva FOREIGN KEY(num_reserva) REFERENCES reserva(num_reserva) ON DELETE RESTRICT ON UPDATE CASCADE,
 CONSTRAINT fk_pacote_hosp FOREIGN KEY(id_hospedagem) REFERENCES hospedagem(id_hospedagem) ON DELETE RESTRICT ON UPDATE CASCADE,
 CONSTRAINT chk_pacote_valor CHECK(valor_total >= 0),
 CONSTRAINT chk_pacote_status CHECK(status IN ('Pendente','Confirmado','Cancelado','Concluido'))
) ENGINE=InnoDB;

CREATE TABLE historico_reserva (
 id_historico INT PRIMARY KEY AUTO_INCREMENT,
 num_reserva INT NOT NULL,
 status_anterior VARCHAR(20) NULL,
 status_novo VARCHAR(20) NOT NULL,
 data_evento DATETIME NOT NULL,
 descricao VARCHAR(180) NOT NULL,
 CONSTRAINT fk_hist_reserva FOREIGN KEY(num_reserva) REFERENCES reserva(num_reserva) ON DELETE RESTRICT ON UPDATE CASCADE,
 CONSTRAINT chk_hist_novo CHECK(status_novo IN ('Pendente','Confirmada','Cancelada','Concluida')),
 CONSTRAINT chk_hist_anterior CHECK(status_anterior IS NULL OR status_anterior IN ('Pendente','Confirmada','Cancelada','Concluida'))
) ENGINE=InnoDB;

