  (900, 900, NULL, 'Pendente', '2027-01-03 10:00:00', 'Estado inicial do registro ficticio');

-- Verificacao: total esperado 3555 registros em 10 tabelas.
SELECT 'passageiro' tabela, COUNT(*) quantidade FROM passageiro
UNION ALL SELECT 'aeronave',COUNT(*) FROM aeronave
UNION ALL SELECT 'aeroporto',COUNT(*) FROM aeroporto
UNION ALL SELECT 'voo',COUNT(*) FROM voo
UNION ALL SELECT 'reserva',COUNT(*) FROM reserva
UNION ALL SELECT 'hotel',COUNT(*) FROM hotel
UNION ALL SELECT 'quarto',COUNT(*) FROM quarto
UNION ALL SELECT 'hospedagem',COUNT(*) FROM hospedagem
UNION ALL SELECT 'pacote',COUNT(*) FROM pacote
UNION ALL SELECT 'historico_reserva',COUNT(*) FROM historico_reserva;

-- Consulta geral de quantidade total
SELECT (SELECT COUNT(*) FROM passageiro)+(SELECT COUNT(*) FROM aeronave)+
 (SELECT COUNT(*) FROM aeroporto)+(SELECT COUNT(*) FROM voo)+
 (SELECT COUNT(*) FROM reserva)+(SELECT COUNT(*) FROM hotel)+
 (SELECT COUNT(*) FROM quarto)+(SELECT COUNT(*) FROM hospedagem)+
 (SELECT COUNT(*) FROM pacote)+(SELECT COUNT(*) FROM historico_reserva) AS total_registros;

